import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    s = list(data[1])

    # Check if n is odd, correct parenthesis sequence must have even length
    if n % 2 != 0:
        print(":(")
        return

    # Count fixed parentheses
    open_count = 0
    close_count = 0
    for char in s:
        if char == '(':
            open_count += 1
        elif char == ')':
            close_count += 1

    # We need total n/2 open and n/2 close parentheses
    needed_open = n // 2 - open_count
    needed_close = n // 2 - close_count

    if needed_open < 0 or needed_close < 0:
        print(":(")
        return

    # Replace '?' from left to right
    # First needed_open are '(', then rest are ')'
    q_idx = 0
    for i in range(n):
        if s[i] == '?':
            if q_idx < needed_open:
                s[i] = '('
                q_idx += 1
            else:
                s[i] = ')'

    # Now verify the conditions:
    # 1. The whole sequence is a correct parenthesis sequence
    # 2. No strict prefix is a correct parenthesis sequence

    balance = 0
    for i in range(n):
        if s[n-1] == '(':
            # Last character cannot be '(' for a correct sequence
            print(":(")
            return

        if s[i] == '(':
            balance += 1
        else:
            balance -= 1

        # Balance should never drop below zero
        if balance < 0:
            print(":(")
            return

        # For strict prefixes (i from 0 to n-2), balance must not be 0
        if i < n - 1 and balance == 0:
            print(":(")
            return

    # Final balance must be 0
    if balance != 0:
        print(":(")
        return

    print("".join(s))

if __name__ == "__main__":
    solve()
